const OX = .15, OY = .85, LAG = .5;
field[i] = distance(pixel, start) / maxDist + (noise[i] - .5) * .5;   // 미리 계산
const F1 = easeInOut(seg(t, T0, T0 + BURN)) * 2, F2 = F1 - LAG;
const d1 = F1 - field[i];                      // > 0 이면 탄 점
color = heat(d1);                              // .05 검정 · .1 진주황 · .2 주황 · .32 노랑 · .46 하양
alphaB = smooth((F2 - field[i]) / SOFT);       // 하얗게 탄 뒤 다음 장면이 나타남

ctx.globalCompositeOperation = 'lighter';
ctx.filter = 'blur(9px)';  ctx.globalAlpha = .55; ctx.drawImage(burnLayer, 0, 0);
ctx.filter = 'blur(22px)'; ctx.globalAlpha = .4;  ctx.drawImage(burnLayer, 0, 0);
